import {readFileSync,mkdirSync} from 'node:fs';
import {pathToFileURL} from 'node:url';
import {resolve} from 'node:path';
import {compileArcMotion} from '../../scripts/v0/optimizer/arc_motion.ts';
import {captureArcFork} from '../../scripts/v0/optimizer/arc_guide_study.ts';
import {connectedArcOptions} from '../../scripts/v0/optimizer/connected_arcs.ts';
import {normalizeCompilerTimeline} from '../../scripts/v0/optimizer/compiler_input.ts';
import {applyJolt,resolveJoltMs} from '../../scripts/produce/seed.ts';
import {replayGalleryTrack,writeGalleryJson,galleryHarnessIdentity} from '../../scripts/gallery/artifacts.ts';
const root='generated/repertoire-workspace-20260930/search',source='generated/connected-repertoire-20260930/review';mkdirSync(root,{recursive:true});
const read=(p:string)=>JSON.parse(readFileSync(p,'utf8')),manifest=read(source+'/manifest.json');
const sourceFiles=['scripts/v0/optimizer/arc_motion.ts','scripts/v0/optimizer/arc_motion_control.ts','scripts/v0/optimizer/arc_attempts.ts','scripts/v0/optimizer/arc_geometry.ts'];
const sourceIdentity=galleryHarnessIdentity(sourceFiles);
const configurations=[['inherited',{}],['recovery',{initialRecoverySamples:80}],['active',{initialRecoverySamples:80,geometryAwareControls:true}],['preview',{initialRecoverySamples:80,geometryAwareControls:true,referencePreview:true}]]as const;
for(const c of manifest.plan.cases.filter((c:any)=>!process.argv[2]||c.id===process.argv[2])){
 const baseline=read(source+'/'+c.id+'-381-baseline.json'),construction=read(source+'/'+c.id+'-381-baseline/construction.json');
 const reference={...baseline,rows:construction.rows},spec=normalizeCompilerTimeline(applyJolt((await import(pathToFileURL(resolve(c.source)).href)).default,resolveJoltMs()));
 const selected=read(source+'/'+c.id+'-381-candidate/construction.json').styles;
 for(const shape of ['fold','strong-ripple'])for(const [method,overrides]of configurations){
  const styles=Object.fromEntries(Object.keys(selected).map(i=>[i,shape==='fold'?selected[i]:{profile:'scallops',profileStart:0,profileStrength:1,rippleCycles:1}]));
  const began=performance.now(),capture=captureArcFork(reference,Math.min(...Object.keys(styles).map(Number)));
  const budget=1000000-capture.physicsFrames;
  const result=compileArcMotion(spec,401,{...connectedArcOptions(spec,budget),...overrides,sectionStyles:styles,collectTrajectoryLoss:true,
   fork:{...capture.fork,continuation:reference.rows.slice(capture.fork.section).map((r:any)=>({control:r.control,incoming:r.incoming,span:r.span}))}});
  const replay=replayGalleryTrack(result.track,c,true),id=c.id+'-'+shape+'-'+method;
  const row={id,caseId:c.id,shape,method,sourceIdentity,sourceTrackHash:baseline.trackHash,styles,valid:replay.grade.score.valid,
   rms:replay.grade.score.valid?replay.grade.score.weightedAxisRms:null,seconds:(performance.now()-began)/1000,
   physicalFrames:capture.physicsFrames+result.stats.sim_frames,preparationFrames:capture.physicsFrames,failure:result.failure,
   proposalDecision:result.proposalDecision,recovery:result.initializationRecovery??[]};
  writeGalleryJson(root,id+'.json',{...row,result,replay});console.log(JSON.stringify(row));
 }
}
if(JSON.stringify(sourceIdentity)!==JSON.stringify(galleryHarnessIdentity(sourceFiles)))throw Error('compiler sources changed during experiment');

import {mkdirSync,readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
const song=process.argv[2],root='generated/repertoire-workspace-20260930';
const windows=song==='luna_bala_44s'?[[6.4,8.55],[24.2,25.8]]:[[1.5,3.5],[4.46,7.87]];
for(const recipe of ['serpentine','terraces'])for(const [name,controls]of Object.entries({late:{profileStrength:1},early:{profileStart:0,profileStrength:1},soft:{profileStart:0,profileStrength:.6},unguided:{profileStart:0,profileStrength:.6,guides:false}})){
 const id=`${song}-${recipe}-${name}`,file=`${root}/requests/${id}.json`,out=`${root}/controls/${id}`;
 const composition={schema:'line.repertoire-plan.v1',title:`${recipe} · ${name}`,song,phrases:windows.map(([start,end],i)=>({title:`Phrase ${i+1}`,start,end,recipe,controls}))};
 writeFileSync(file,JSON.stringify({composition,seed:401,baselineBudget:1000000,compositionBudget:1000000}));
 const result=spawnSync(process.execPath,['--import','tsx','scripts/produce/repertoire.ts',`--request=${file}`,`--out=${out}`],{env:{...process.env,LR_ENGINE:'wasm'},encoding:'utf8',maxBuffer:1024*1024});
 writeFileSync(`${root}/${id}.log`,result.stdout+result.stderr);
 if(result.status)console.log(JSON.stringify({id,error:result.status}));else{const m=JSON.parse(readFileSync(`${out}/manifest.json`));const c=m.cells[1];console.log(JSON.stringify({id,valid:c.valid,rms:c.qualityRms,seconds:c.compileMs/1000,physics:c.physicalFrames}));}
}

import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {sha} from '../../benchmark/v3/model.ts';
import {loadMusicCase} from '../../scripts/produce/music_artifacts.ts';
import {composeRepertoire} from '../../scripts/v0/optimizer/repertoire_composition.ts';
import {writeGalleryJson} from '../../scripts/gallery/artifacts.ts';
const root='generated/repertoire-workspace-20260930';const read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
for(const name of process.argv.slice(2)){
 const dir=`${root}/${name}`,m=read(dir+'/manifest.json'),b=m.cells[0],a=m.cells[1],record=read(dir+'/'+b.path),construction=read(dir+'/'+b.id+'/construction.json');
 const {spec}=await loadMusicCase(m.plan.cases[0],m.plan.jolt);
 const source={track:record.track,rows:construction.rows,report:read(dir+'/'+b.reportPath)};
 const now=composeRepertoire(spec,a.seed,source,m.plan.composition,a.allowance);
 assert.equal(sha(JSON.stringify(now.result.track)),a.trackHash,name);assert.equal(now.physicalFrames,a.physicalFrames,name);
 assert.deepEqual(now.result.report,read(dir+'/'+a.reportPath),name);assert.deepEqual(now.fragmentSections,a.construction.fragmentSections);
 writeGalleryJson(root,'delivery-'+name.replaceAll('/','-')+'.json',{name,trackHash:a.trackHash,physicalFrames:a.physicalFrames,exactTrackReportFragmentsAndWork:true});console.log(name+' exact');
}

import assert from 'node:assert/strict';import {writeFileSync} from 'node:fs';
const origin='http://127.0.0.1:8767/api/repertoire/';const api=async(path,data)=>{const r=await fetch(origin+path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const v=await r.json();assert.ok(r.ok,JSON.stringify(v));return v;};
const old=(await api('jobs')).jobs.find(j=>j.id==='9946ec69-adbb-4a6b-91db-59024912671f');assert.equal(old.status,'complete');
await api(`jobs/${old.id}/render`,{});
const {job}=await api('compile',{...old.request,seed:403,composition:{...old.request.composition,title:'Concurrent worker check'}});
const jobs=(await api('jobs')).jobs,renderer=jobs.find(j=>j.id===old.id),compiler=jobs.find(j=>j.id===job.id);
assert.equal(renderer.render,'rendering');assert.equal(compiler.status,'compiling');await api(`jobs/${job.id}/cancel`,{});
writeFileSync('generated/repertoire-workspace-20260930/worker-lane-checks.json',JSON.stringify({observedIndependentWorkers:true,renderer,compiler,cancelledCompiler:job.id},null,2)+'\n');console.log('Independent render and compiler workers verified; probe compiler cancelled.');

import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {readFileSync,writeFileSync,existsSync} from 'node:fs';
const request={composition:{schema:'line.repertoire-plan.v1',title:'Shutdown ownership check',song:'luna_bala_44s',phrases:[{title:'Long folds',start:5,end:38,recipe:'fold'}]},seed:404,baselineBudget:1000000,compositionBudget:4000000};
const response=await fetch('http://127.0.0.1:8767/api/repertoire/compile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)});assert.ok(response.ok);const {job}=await response.json();assert.equal(job.status,'compiling');
const parent=Number(execFileSync('lsof',['-t','-iTCP:8767','-sTCP:LISTEN'],{encoding:'utf8'}).trim());
const children=readFileSync(`/proc/${parent}/task/${parent}/children`,'utf8').trim().split(/\s+/).filter(Boolean).map(Number);assert.ok(children.length);
process.kill(parent,'SIGTERM');
for(let i=0;i<40&&children.some(pid=>existsSync(`/proc/${pid}`));i++)await new Promise(r=>setTimeout(r,100));
assert.ok(children.every(pid=>!existsSync(`/proc/${pid}`)),'owned child survived graceful shutdown');
const saved=JSON.parse(readFileSync(`generated/repertoire-jobs/${job.id}/job.json`));assert.equal(saved.status,'error');
writeFileSync('generated/repertoire-workspace-20260930/shutdown-check.json',JSON.stringify({job:saved.id,status:saved.status,ownedChildrenTerminated:children.length,noCompletedOutput:!existsSync(`generated/repertoire-jobs/${job.id}/output/manifest.json`)},null,2)+'\n');console.log('Owned workers stopped and interrupted work was not reported complete.');

