import json,pathlib,hashlib,re,subprocess
root=pathlib.Path('generated/repertoire-workspace-20260930')
def read(p):return json.loads(pathlib.Path(p).read_text())
def digest(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def artifact(p,checked=False):
 p=pathlib.Path(p);h=digest(p)
 if checked:assert pathlib.Path(str(p)+'.sha256').read_text().strip()==h,p
 return {'path':str(p),'sha256':h}
def source(p):return {**artifact(p),'source':pathlib.Path(p).read_text()}
def compiler(x):return {k:x[k]for k in ['head','candidateFingerprint','compilerSourceFingerprint','engineArtifactFingerprint','compilerEnvironment']}
def failure(x):return {'count':len(x),'examples':x[:3]}
def cell(c):
 keys=['id','caseId','method','seed','jitter','allowance','valid','qualityRms','compileMs','physicalFrames','lines','trackHash','failure','geometryVerification','contactSummary','collisionSha256']
 r={k:c[k]for k in keys if k in c};r['score']={**c['score'],'hardFailures':failure(c['score']['hardFailures'])};r['qualityRmsWhenValid']=c['qualityRms']if c['valid']else None
 r['changedSectionMeasurements']=[s for s in c['sections']if s['section']in c['construction']['changedSections']]
 r['construction']={k:c['construction'].get(k)for k in ['styles','phrases','fragmentSections','boundaryFrame','prefixFrames','changedMotionFrames','changedSections','baseTrackHash']}
 r['stages']=[{k:a.get(k)for k in ['stage','kind','section','allowance','physicalFrames','preparationFrames','valid','failure','boundaryFrame']}for a in c['construction'].get('stages',[]) or []]
 return r
def contact_summary(path):
 data=read(path);supports=[]
 for row in data['rows']:
  for s in row['supports']:
   bins=[set()for _ in range(4)]
   for t in s['contactTimeline']:
    for c in t['main']:
     if c['profilePhase']is not None:bins[min(3,int(c['profilePhase']*4))].add(t['frame'])
   first=set.union(*bins[:2]);second=set.union(*bins[2:]);ordered=bool(first and second and min(first)<max(second))
   supports.append({k:s[k]for k in ['section','start','end','profile','strength','profileStart','mainContactFrames','reshapedMainContactFrames','guideContactFrames']}|{'scheduleQuarterContactFrames':[len(x)for x in bins],'bothHalvesContactedInOrder':ordered})
 return {'artifact':artifact(path,True),'interpretation':'Actual main-rail collision frames by heading-schedule quarter, not time/distance or continuous traversal. First-half contact before later second-half contact may contain ballistic gaps; all rider points count. No artistic or necessity certificate.','supports':supports}
search=[]
for p in sorted((root/'search').glob('*.json')):
 r=read(p);search.append({**artifact(p,True),**{k:r[k]for k in ['id','caseId','shape','method','sourceIdentity','sourceTrackHash','styles','valid','rms','seconds','physicalFrames','preparationFrames','failure','proposalDecision','recovery']}})
assert len(search)==24 and sum(s['valid']for s in search)==21
for r in search:
 for path,h in r['sourceIdentity'].items():assert hashlib.sha256(subprocess.check_output(['git','show','c2e05858:'+path])).hexdigest()==h
controls=[]
for p in sorted((root/'controls').glob('*/manifest.json')):
 m=read(p);controls.append({'manifest':artifact(p,True),'composition':m['plan']['composition'],'compiler':compiler(m['plan']['compiler']),
  'baseline':cell(m['cells'][0]),'alternative':cell(m['cells'][1]),'contacts':contact_summary(p.parent/'contacts.json')})
assert len(controls)==16 and all(x['alternative']['valid']for x in controls)
arrangements=[];videos=[]
for name in ['arrangements/preset-0','arrangements/preset-1','arrangements/preset-2','arrangements/preset-3','reserved-tiki']:
 d=root/name;m=read(d/'manifest.json');assert all(c['valid']for c in m['cells'])
 arrangements.append({'manifest':artifact(d/'manifest.json',True),'plan':artifact(d/'plan.json',True),'composition':m['plan']['composition'],'compiler':compiler(m['plan']['compiler']),
  'jolt':m['plan']['jolt'],'cells':[cell(c)for c in m['cells']],
  'inputs':[{k:c[k]for k in ['id','specSha256','audioSha256','analysisSha256','jitter','render']}for c in m['plan']['cases']],
  'deliveryParity':read(root/('delivery-'+name.replace('/','-')+'.json'))})
 for c in m['cells']:
  v=read(d/(c['id']+'.video.json'));assert v['identity']['cellSha256']==c['sha256'];assert v['identity']['planSha256']==m['planSha256']
  for part in ['full','excerpt']:
   media=v[part];assert digest(d/media['path'])==media['sha256'];probe=media['probe'];stream=next(s for s in probe['streams']if s['codec_type']=='video');assert stream['width']==1080 and stream['height']==1920 and stream['avg_frame_rate']=='60/1';assert any(s['codec_type']=='audio'for s in probe['streams'])
  videos.append({'record':artifact(d/(c['id']+'.video.json'),True),'cell':c['id'],'full':{'path':str((d/v['full']['path']).resolve()),'sha256':v['full']['sha256']},'excerpt':{'path':str((d/v['excerpt']['path']).resolve()),'sha256':v['excerpt']['sha256']},'format':'1080x1920 60fps with audio, full production pipeline','reusedFrom':v.get('reusedFrom')})
validation={}
for name in ['canonical-parity.json','delivery-canonical-parity.json','legacy-harness-parity.json','typescript-comparison.json','workspace-checks.json','worker-lane-checks.json','shutdown-check.json','arrangement-native-checks.json','reserved-native-checks.json','control-native-checks.json']:
 p=root/name;data=read(p);validation[name]={'artifact':artifact(p),'result':data}
assert validation['delivery-canonical-parity.json']['result']['runs']==352
for name in ['arrangement-native-checks.json','reserved-native-checks.json','control-native-checks.json']:assert validation[name]['result']['maxBodyPointError']==0
assert validation['typescript-comparison.json']['result']['new']==[]
validation['focusedTests']={'passed':39,'files':6,'log':artifact(root/'delivery-tests.log')}
validation['cacheTest']={'passed':1,'log':artifact(root/'cache-tests.log')}
validation['actualApiRendering']={}
for id in ['b532cd32-1918-4dc9-8f9d-5a0c98de6b55','9946ec69-adbb-4a6b-91db-59024912671f']:
 p=pathlib.Path('generated/repertoire-jobs')/id;job=read(p/'job.json');assert job['status']=='complete'and job['render']=='complete'
 validation['actualApiRendering'][id]={'job':artifact(p/'job.json'),'renderLog':artifact(p/'render.log'),'complete':True,'manifest':artifact(p/'output/manifest.json',True)}
stress=read(root/'stress-failure/manifest.json');assert not stress['cells'][1]['valid'];assert not (root/'stress-failure'/f"{stress['cells'][1]['id']}.video.json").exists()
normal=[]
for p in [*(root/'controls').glob('*/manifest.json'),*(root/'arrangements').glob('*/manifest.json'),root/'reserved-tiki/manifest.json',root/'stress-failure/manifest.json']:
 m=read(p)
 for c in m['cells']:
  r=read(p.parent/c['path']);assert all(l['type']==0 for l in r['track']['lines']);normal.append(c['trackHash'])
x={'schema':'line.repertoire-workspace-evidence.v1','date':'2026-09-30','scope':'Integrated composition workflow, shared search diagnosis, functional construction controls and complete musical arrangements. Frozen authored music, normal lines, unchanged judge.',
 'compiler':{'experimentalArchive':'c2e05858','deliveredCore':'bddc8bba','archivedOptions':['geometryAwareControls','referencePreview'],'keptCompositionSearch':{'initialRecoverySamples':80}},
 'search':search,'controls':controls,'arrangements':arrangements,'videos':videos,'stressFailure':{'manifest':artifact(root/'stress-failure/manifest.json',True),'cell':cell(stress['cells'][1])},
 'validation':validation,'normalLineAudit':{'recordEntries':len(normal),'distinctTracks':len(set(normal)),'allNormal':True},
 'visualInspection':{'nativePreview':artifact(root/'serpentine-preview.png'),'productionFramePanel':artifact(root/'video-inspection/panel.png'),'interpretation':'Sampled frames checked for native artwork, linework and complete production layers. This is not owner approval or a full-video artistic judgment.'},
 'limits':['Three previously known songs; zero authored jitter. Repeated seeds/tracks are not independent robustness evidence.','Tiki intervention windows [24,26.5] and [44,46] declared before development. Other experiments are development or diagnosis.','RMS is musical adherence, not aesthetic quality. Contact counts and schedule coverage do not prove continuous sliding or necessity.','Only normal type-0 physical lines. No new defaults, music specification, benchmark or scorer.','Two search ideas were archived after mixed/negative evidence; no ceiling is claimed.'],
 'reproduction':{'sources':[source(root/p)for p in ['probe-search.ts','probe-repertoire.mjs','check-delivery-composition.ts','check-worker-lanes.mjs','check-shutdown.mjs']],
  'commands':['LR_ENGINE=wasm node --import tsx scripts/produce/repertoire.ts --request=REQUEST.json --out=FRESH_OUTPUT',
   'LR_ENGINE=wasm node --import tsx scripts/produce/render_repertoire.ts --study=OUTPUT',
   'node scripts/gallery/check_repertoire_workspace.mjs',
   'LR_ENGINE=wasm node --import tsx scripts/benchmark/v4.ts eval --compiler-root=/tmp/line-repertoire-workspace-20260930 --out=generated/repertoire-workspace-20260930/delivery-canonical --jobs=8 --seeds=16,17'],
  'packager':source(__file__)}}
out=pathlib.Path('docs/evidence/repertoire-workspace-20260930.json');out.write_text(json.dumps(x,separators=(',',':'))+'\n');pathlib.Path(str(out)+'.sha256').write_text(digest(out)+'\n')
print(json.dumps({'artifact':str(out),'bytes':out.stat().st_size,'searchCalls':len(search),'controls':len(controls),'arrangements':len(arrangements),'videoRecords':len(videos),'normal':x['normalLineAudit']}))
